package dns.resolver

import scala.collection.mutable
import scala.util.{Try, Success, Failure}

// Multi-tenant DNS resolver with configurable record overrides
object TenantConfig {
  // Base configuration shared across all tenants (immutable defaults)
  private val baseConfig: Map[String, Any] = Map(
    "ttl" -> 300,
    "maxRetries" -> 3,
    "timeout" -> 5000,
    "allowRecursion" -> true,
    "forwarders" -> List("8.8.8.8", "8.8.4.4")
  )

  // Per-tenant override chains
  private val tenantOverrides: mutable.Map[String, mutable.Map[String, Any]] = mutable.Map()

  def getOrCreateTenant(tenantId: String): mutable.Map[String, Any] = {
    tenantOverrides.getOrElseUpdate(tenantId, mutable.Map())
  }

  def resolve(tenantId: String, key: String): Option[Any] = {
    tenantOverrides.get(tenantId).flatMap(_.get(key)).orElse(baseConfig.get(key))
  }
}

case class DnsRecord(name: String, recordType: String, value: String, ttl: Int)

class TenantDnsResolver(tenantId: String) {
  private val localCache: mutable.Map[String, DnsRecord] = mutable.Map()
  private val tenantConfig = TenantConfig.getOrCreateTenant(tenantId)

  // Allowed configuration keys for tenant-level settings
  private val allowedKeys: Set[String] = Set("ttl", "maxRetries", "timeout", "allowRecursion", "forwarders")

  def configureTenant(settings: Map[String, Any]): Unit = {
    settings.foreach { case (key, value) =>
      applyConfigPath(key, value)
    }
  }

  // Supports dotted path notation for nested config: "dns.upstream.primary"
  private def applyConfigPath(path: String, value: Any): Unit = {
    val segments = path.split("\\.")
    if (segments.length == 1) {
      if (allowedKeys.contains(path)) {
        tenantConfig(path) = value
      }
    } else {
      // For nested paths, only allow tenant-scoped configuration
      traverseAndSet(segments, value)
    }
  }

  private def traverseAndSet(segments: Array[String], value: Any): Unit = {
    val head = segments.head
    val tail = segments.tail
    val leafKey = tail.last

    // Reject any attempt to modify shared/base/prototype configuration
    if (head == "base" || head == "default" || head == "__proto__") {
      // Silently reject - tenant cannot modify shared configuration
      return
    } else {
      // Normal nested config for this tenant only
      val compositeKey = segments.mkString(".")
      tenantConfig(compositeKey) = value
    }
  }

  def lookup(domain: String): Option[DnsRecord] = {
    localCache.get(domain).orElse {
      val ttl = TenantConfig.resolve(tenantId, "ttl").collect { case i: Int => i }.getOrElse(300)
      val allowRecursion = TenantConfig.resolve(tenantId, "allowRecursion").collect { case b: Boolean => b }.getOrElse(true)

      if (allowRecursion) {
        performRecursiveLookup(domain, ttl)
      } else {
        None
      }
    }
  }

  private def performRecursiveLookup(domain: String, ttl: Int): Option[DnsRecord] = {
    val forwarders = TenantConfig.resolve(tenantId, "forwarders").collect {
      case l: List[_] => l.collect { case s: String => s }
    }.getOrElse(List("8.8.8.8"))

    val maxRetries = TenantConfig.resolve(tenantId, "maxRetries").collect { case i: Int => i }.getOrElse(3)

    // Simulate DNS resolution with configured forwarders
    simulateUpstreamQuery(domain, forwarders, maxRetries, ttl)
  }

  private def simulateUpstreamQuery(domain: String, forwarders: List[String], retries: Int, ttl: Int): Option[DnsRecord] = {
    // In production this would make actual DNS queries
    val record = DnsRecord(domain, "A", "192.168.1.1", ttl)
    localCache(domain) = record
    Some(record)
  }

  def getTenantIsolationStatus: Map[String, Any] = {
    Map(
      "tenantId" -> tenantId,
      "configKeys" -> tenantConfig.keys.toList,
      "allowRecursion" -> TenantConfig.resolve(tenantId, "allowRecursion"),
      "forwarders" -> TenantConfig.resolve(tenantId, "forwarders")
    )
  }
}

// API endpoint handler
object DnsResolverService {
  private val resolvers: mutable.Map[String, TenantDnsResolver] = mutable.Map()

  def handleConfigUpdate(tenantId: String, configJson: Map[String, Any]): Either[String, String] = {
    val resolver = resolvers.getOrElseUpdate(tenantId, new TenantDnsResolver(tenantId))
    Try(resolver.configureTenant(configJson)) match {
      case Success(_) => Right(s"Configuration updated for tenant $tenantId")
      case Failure(e) => Left(s"Error: ${e.getMessage}")
    }
  }

  def handleLookup(tenantId: String, domain: String): Either[String, DnsRecord] = {
    resolvers.get(tenantId) match {
      case Some(resolver) => resolver.lookup(domain).toRight("Domain not found")
      case None => Left("Tenant not configured")
    }
  }
}
